#!/usr/bin/env python3
"""Reference implementation of the mobile upload wire format.

Writes contract-vectors.json, which is asserted byte-for-byte by
  - Go:     internal/httpapi/mobile_client_contract_test.go (the server accepts it)
  - Kotlin: modules/nmcp-uploader/android/src/test/.../MultipartFormatTest.kt
  - Swift:  modules/nmcp-uploader/tests/swift (swift test)
Run: python3 -I generate_vectors.py > contract-vectors.json
"""
import hashlib
import json
import re
import unicodedata

ATTR = set(b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$&+-.^_`|~")
MIME = re.compile(r"^[A-Za-z0-9][A-Za-z0-9!#$&^_.+-]*/[A-Za-z0-9][A-Za-z0-9!#$&^_.+-]*$")


def ascii_fallback(name):
    # one "_" per UTF-16 code unit that is not printable ASCII, or is '"' or '\'
    units = name.encode("utf-16-le")
    out = []
    for i in range(0, len(units), 2):
        u = units[i] | units[i + 1] << 8
        out.append(chr(u) if 0x20 <= u <= 0x7E and u not in (0x22, 0x5C) else "_")
    return "".join(out)


def rfc5987(name):
    return "".join(chr(b) if b in ATTR else "%%%02X" % b for b in name.encode("utf-8"))


def content_type(mime):
    m = mime.strip()
    return m if MIME.match(m) and not m.lower().startswith("multipart/") else "application/octet-stream"


def key(platform, item_id, sha, name):
    return "nmcp1-" + hashlib.sha256(f"{platform}|{item_id}|{sha}|{name}".encode("utf-8")).hexdigest()


def server_filename(name):
    # mirrors internal/upload.NormalizeFilename for the names used below
    base = [c for c in name.replace("\\", "/").split("/") if c][-1]
    return unicodedata.normalize("NFC", base)


CASES = [
    ("android", "img:1000001234", "IMG_20261116_101500.jpg", "image/jpeg", "\xff\xd8jpeg-bytes\r\n--nmcp-fake\r\n"),
    ("android", "vid:42", "VID_写真 (1).mp4", "video/mp4", "mp4\x00bytes"),
    ("android", "img:7", "100% *final*'s!&~.png", "", "png"),
    ("android", "img:8", "x.dat", "multipart/mixed", "x"),
    ("ios", "8F3C2A10-1B2C-4D5E-8F90-ABCDEF012345/L0/001#1", "IMG_0001.HEIC", "image/heic", "heic-bytes"),
    ("ios", "8F3C2A10-1B2C-4D5E-8F90-ABCDEF012345/L0/001#9", "IMG_0001.MOV", "video/quicktime", "live-photo-video"),
    ("ios", "A#1", "émoji\U0001F600 \"q\".jpg", "image/jpeg", "nfc"),
]
BOUNDARY = "nmcp-0123456789abcdef0123456789abcdef"

out = []
for platform, item_id, name, mime, content in CASES:
    body = content.encode("latin-1")
    sha = hashlib.sha256(body).hexdigest()
    head = (
        f"--{BOUNDARY}\r\n"
        f"Content-Disposition: form-data; name=\"file\"; filename=\"{ascii_fallback(name)}\"; filename*=UTF-8''{rfc5987(name)}\r\n"
        f"Content-Type: {content_type(mime)}\r\n\r\n"
    )
    out.append({
        "platform": platform,
        "itemId": item_id,
        "name": name,
        "mime": mime,
        "contentLatin1": content,
        "boundary": BOUNDARY,
        "expected": {
            "contentSha256": sha,
            "idempotencyKey": key(platform, item_id, sha, name),
            "filenameFallback": ascii_fallback(name),
            "filenameStar": rfc5987(name),
            "contentType": content_type(mime),
            "head": head,
            "tail": f"\r\n--{BOUNDARY}--\r\n",
            "serverFilename": server_filename(name),
        },
    })

print(json.dumps({
    "keyFormat": "nmcp1- + lowercase hex SHA-256 of UTF-8 \"<platform>|<itemId>|<contentSha256 hex>|<filename>\"",
    "note": "contentLatin1: each char is one byte (U+0000..U+00FF). Generated by generate_vectors.py; do not edit by hand.",
    "cases": out,
}, ensure_ascii=False, indent=2))
